mapper.update:
update oc_ai_conversation
set title = case
        when title = '新会话' and #{generatedTitle} is not null
            then #{generatedTitle}
        else title
    end,
    last_message_time = sysdate(),
    update_by = #{updateBy},
    update_time = sysdate()
where conversation_id = #{conversationId}
  and user_id = #{userId}
  and status = '0'
  and del_flag = '0'
